/****************************************************************************
 * Name: d13x_i2c_initialize
 *
 * Description:
 *   初始化指定的 I2C 总线
 *
 ****************************************************************************/

int d13x_i2c_initialize(int bus)
{
  struct d13x_i2c_priv_s *priv;
  uint32_t reg;

  switch (bus)
    {
#ifdef CONFIG_D13X_I2C0
      case 0:
        priv = &g_i2c0_priv;
        break;
#endif
#ifdef CONFIG_D13X_I2C1
      case 1:
        priv = &g_i2c1_priv;
        break;
#endif
#ifdef CONFIG_D13X_I2C2
      case 2:
        priv = &g_i2c2_priv;
        break;
#endif
      default:
        return -EINVAL;
    }

  /* 使能 I2C 模块时钟 */

  reg = getreg32(D13X_CMU_BASE + 0x844 + bus * 4);
  reg |= (1 << 13) | (1 << 12) | (1 << 8);
  putreg32(reg, D13X_CMU_BASE + 0x844 + bus * 4);

  /* 禁用 I2C 以配置 */

  dw_i2c_disable(priv);

  /* 配置为主模式, Fast Mode (400kHz), 重启使能 */

  reg = DW_I2C_CTL_MASTER | DW_I2C_CTL_SPEED_FS | DW_I2C_CTL_RESTART_EN;
  dw_i2c_write(priv, DW_I2C_CTL, reg);

  /* 配置 SCL 时序 (400kHz @ I2C模块时钟)
   * 根据 luban-lite HAL, I2C模块时钟为24MHz (I2C_DEFALT_CLOCK)
   * FS_SCL_HCNT = 24000000 / (2 * 400000) - 8 = 22
   * FS_SCL_LCNT = 24000000 / (2 * 400000) - 1 = 29
   */

  dw_i2c_write(priv, DW_I2C_FS_SCL_HCNT, 22);
  dw_i2c_write(priv, DW_I2C_FS_SCL_LCNT, 29);

  /* 设置 SDA 保持时间 */

  dw_i2c_write(priv, DW_I2C_SDA_HOLD, 12);

  /* 设置 TX/RX FIFO 阈值 */

  dw_i2c_write(priv, DW_I2C_INTR_CLR, 0xFFFF);
  dw_i2c_write(priv, DW_I2C_INTR_MASK, 0);

  /* 使能 I2C */

  dw_i2c_enable(priv);

  /* 初始化互斥锁 */

  nxmutex_init(&priv->lock);

  iinfo("I2C%d 初始化完成, 基地址=0x%08X\n", bus, priv->base);

  return OK;
}

