/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_fb.c
 *
 * D13x 最小化帧缓冲驱动 (基于 D12x 参考代码简化)
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/kmalloc.h>
#include <nuttx/cache.h>
#include <nuttx/video/fb.h>
#include <debug.h>
#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* 默认显示分辨率 (4.3寸面板: 1024x600) */

#define D13X_FB_WIDTH           1024
#define D13X_FB_HEIGHT          600
#define D13X_FB_BPP             32      /* RGB888 */
#define D13X_FB_STRIDE          (D13X_FB_WIDTH * (D13X_FB_BPP / 8))
#define D13X_FB_SIZE            (D13X_FB_STRIDE * D13X_FB_HEIGHT)

/* 双缓冲 */

#define D13X_FB_BUFFER_COUNT    2

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct d13x_fb_info_s
{
  bool                initialized;
  bool                power_on;
  void               *fb_mem;        /* 帧缓冲内存 */
  size_t              fb_size;       /* 单帧大小 */
  struct fb_vtable_s  vtable;        /* NuttX FB 接口 */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct d13x_fb_info_s g_d13x_fb;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int d13x_fb_getvideoinfo(struct fb_vtable_s *vtable,
                                struct fb_videoinfo_s *vinfo)
{
  if (!vtable || !vinfo)
    {
      return -EINVAL;
    }

  vinfo->fmt = FB_FMT_RGB32;     /* RGB888 */
  vinfo->nplanes = 1;
  vinfo->xres = D13X_FB_WIDTH;
  vinfo->yres = D13X_FB_HEIGHT;

  iinfo("getvideoinfo: %dx%d RGB888\n", D13X_FB_WIDTH, D13X_FB_HEIGHT);
  return OK;
}

static int d13x_fb_getplaneinfo(struct fb_vtable_s *vtable, int planeno,
                                struct fb_planeinfo_s *pinfo)
{
  struct d13x_fb_info_s *fbi = &g_d13x_fb;

  if (!vtable || planeno != 0 || !pinfo)
    {
      return -EINVAL;
    }

  pinfo->bpp = D13X_FB_BPP;
  pinfo->display = 0;
  pinfo->stride = D13X_FB_STRIDE;
  pinfo->fblen = fbi->fb_size * D13X_FB_BUFFER_COUNT;
  pinfo->fbmem = fbi->fb_mem;
  pinfo->xres_virtual = D13X_FB_WIDTH;
  pinfo->yres_virtual = D13X_FB_HEIGHT * D13X_FB_BUFFER_COUNT;

  iinfo("getplaneinfo: %d bpp, stride=%d, fblen=%d\n",
        D13X_FB_BPP, D13X_FB_STRIDE, pinfo->fblen);
  return OK;
}

static int d13x_fb_setpower(struct fb_vtable_s *vtable, int power)
{
  struct d13x_fb_info_s *fbi = &g_d13x_fb;

  if (!vtable)
    {
      return -EINVAL;
    }

  fbi->power_on = (power > 0);
  iinfo("setpower: %s\n", fbi->power_on ? "ON" : "OFF");
  return OK;
}

static int d13x_fb_getpower(struct fb_vtable_s *vtable)
{
  struct d13x_fb_info_s *fbi = &g_d13x_fb;

  if (!vtable)
    {
      return -EINVAL;
    }

  return fbi->power_on ? 1 : 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: up_fbinitialize
 *
 * Description:
 *   初始化 D13x 帧缓冲硬件
 *
 ****************************************************************************/

int up_fbinitialize(int display)
{
  struct d13x_fb_info_s *fbi = &g_d13x_fb;
  void *fb_mem;

  if (fbi->initialized)
    {
      return OK;
    }

  iinfo("Initializing D13x framebuffer...\n");

  /* 分配帧缓冲内存 (双缓冲) */

  fb_size = D13X_FB_SIZE * D13X_FB_BUFFER_COUNT;
  fb_mem = kmm_memalign(64, fb_size);  /* 64字节对齐 (cache line) */
  if (!fb_mem)
    {
      ierr("Failed to allocate framebuffer memory (%d bytes)\n", fb_size);
      return -ENOMEM;
    }

  /* 清零帧缓冲 */

  memset(fb_mem, 0, fb_size);

  /* 初始化 fb_info */

  fbi->fb_mem = fb_mem;
  fbi->fb_size = D13X_FB_SIZE;
  fbi->power_on = false;

  /* 设置 fb_vtable_s 接口 */

  memset(&fbi->vtable, 0, sizeof(fbi->vtable));
  fbi->vtable.getvideoinfo = d13x_fb_getvideoinfo;
  fbi->vtable.getplaneinfo = d13x_fb_getplaneinfo;
  fbi->vtable.setpower = d13x_fb_setpower;
  fbi->vtable.getpower = d13x_fb_getpower;

  fbi->initialized = true;

  iinfo("D13x framebuffer initialized: %dx%d, %d bpp, %d bytes\n",
        D13X_FB_WIDTH, D13X_FB_HEIGHT, D13X_FB_BPP, fb_size);

  return OK;
}

/****************************************************************************
 * Name: up_fbgetvplane
 *
 * Description:
 *   获取帧缓冲 vtable
 *
 ****************************************************************************/

struct fb_vtable_s *up_fbgetvplane(int display, int vplane)
{
  struct d13x_fb_info_s *fbi = &g_d13x_fb;

  if (vplane != 0 || !fbi->initialized)
    {
      return NULL;
    }

  return &fbi->vtable;
}

/****************************************************************************
 * Name: up_fbuninitialize
 *
 * Description:
 *   反初始化帧缓冲
 *
 ****************************************************************************/

void up_fbuninitialize(int display)
{
  struct d13x_fb_info_s *fbi = &g_d13x_fb;

  if (!fbi->initialized)
    {
      return;
    }

  /* 释放帧缓冲内存 */

  if (fbi->fb_mem)
    {
      kmm_free(fbi->fb_mem);
      fbi->fb_mem = NULL;
    }

  fbi->initialized = false;
  iinfo("D13x framebuffer uninitialized\n");
}

