/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_de.c
 *
 * D13x 显示引擎 (Display Engine) 驱动 (简化版)
 * 寄存器来源: luban-lite aic_hal_de.h
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <debug.h>
#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* 显示引擎寄存器偏移 (来源: luban-lite aic_hal_de.h) */

#define DE_BASE_OFFSET          0x18A00000

/* 全局控制 */

#define G_BASE                  0x000
#define DE_CTRL                 (G_BASE + 0x000)
#define DE_CONFIG_UPDATE        (G_BASE + 0x008)

/* UI 图层控制 */

#define UI_BASE                 0x0a0
#define UI_LAYER_CTRL           (UI_BASE + 0x000)
#define UI_LAYER_SIZE           (UI_BASE + 0x004)
#define UI_RECT_INPUT_SIZE(n)   (UI_BASE + 0x020 + 0x10 * (n))
#define UI_RECT_OFFSET(n)       (UI_BASE + 0x024 + 0x10 * (n))
#define UI_RECT_STRIDE(n)       (UI_BASE + 0x028 + 0x10 * (n))
#define UI_RECT_ADDR(n)         (UI_BASE + 0x02c + 0x10 * (n))

/* 混合控制 */

#define BLENDING_BASE           0x100
#define BLENDING_BG_COLOR       (BLENDING_BASE + 0x000)
#define BLENDING_OUTPUT_SIZE    (BLENDING_BASE + 0x004)

/* 时序控制 */

#define TIMING_BASE             0x1d0
#define TIMING_CTRL             (TIMING_BASE + 0x000)
#define TIMING_INIT             (TIMING_BASE + 0x004)
#define TIMING_ACTIVE_SIZE      (TIMING_BASE + 0x010)
#define TIMING_H_PORCH          (TIMING_BASE + 0x014)
#define TIMING_V_PORCH          (TIMING_BASE + 0x018)
#define TIMING_SYNC_PLUSE       (TIMING_BASE + 0x01c)

/* 控制位域 */

#define DE_CONFIG_UPDATE_EN     BIT(0)
#define UI_LAYER_CTRL_EN        BIT(0)
#define TIMING_CTRL_EN          BIT(0)

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline void de_write(uint32_t offset, uint32_t value)
{
  putreg32(value, D13X_DE_BASE + offset);
}

static inline uint32_t de_read(uint32_t offset)
{
  return getreg32(D13X_DE_BASE + offset);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: d13x_de_init
 *
 * Description:
 *   初始化显示引擎
 *
 ****************************************************************************/

int d13x_de_init(uint32_t width, uint32_t height)
{
  iinfo("Initializing Display Engine: %dx%d\n", width, height);

  /* 配置更新使能 */

  de_write(DE_CONFIG_UPDATE, DE_CONFIG_UPDATE_EN);

  /* 配置混合输出大小 */

  de_write(BLENDING_OUTPUT_SIZE, (height << 16) | width);
  de_write(BLENDING_BG_COLOR, 0x000000);  /* 黑色背景 */

  /* 配置 UI 图层 0 */

  de_write(UI_LAYER_SIZE, (height << 16) | width);

  /* 配置矩形区域 0 */

  de_write(UI_RECT_INPUT_SIZE(0), (height << 16) | width);
  de_write(UI_RECT_OFFSET(0), 0);
  de_write(UI_RECT_STRIDE(0), width * 4);  /* RGB888: 4 bytes/pixel */

  /* 使能 UI 图层 */

  de_write(UI_LAYER_CTRL, UI_LAYER_CTRL_EN);

  /* 配置时序 */

  /* 主动区域 */

  de_write(TIMING_ACTIVE_SIZE, (height << 16) | width);

  /* 前后肩 (简化配置) */

  de_write(TIMING_H_PORCH, (160 << 16) | 160);  /* HBP=160, HFP=160 */
  de_write(TIMING_V_PORCH, (20 << 16) | 10);    /* VBP=20, VFP=10 */
  de_write(TIMING_SYNC_PLUSE, (8 << 16) | 40);  /* VSW=8, HSW=40 */

  /* 使能时序 */

  de_write(TIMING_CTRL, TIMING_CTRL_EN);

  /* 触发配置更新 */

  de_write(DE_CONFIG_UPDATE, DE_CONFIG_UPDATE_EN);

  iinfo("Display Engine initialized\n");
  return OK;
}

/****************************************************************************
 * Name: d13x_de_set_framebuffer
 *
 * Description:
 *   设置帧缓冲地址
 *
 ****************************************************************************/

void d13x_de_set_framebuffer(uint32_t addr)
{
  /* 设置矩形区域 0 的帧缓冲地址 */

  de_write(UI_RECT_ADDR(0), addr);

  /* 触发配置更新 */

  de_write(DE_CONFIG_UPDATE, DE_CONFIG_UPDATE_EN);

  iinfo("DE framebuffer set to 0x%08x\n", addr);
}

/****************************************************************************
 * Name: d13x_de_enable
 *
 * Description:
 *   使能显示引擎
 *
 ****************************************************************************/

void d13x_de_enable(void)
{
  /* 使能时序 */

  de_write(TIMING_CTRL, TIMING_CTRL_EN);

  /* 触发配置更新 */

  de_write(DE_CONFIG_UPDATE, DE_CONFIG_UPDATE_EN);

  iinfo("Display Engine enabled\n");
}

/****************************************************************************
 * Name: d13x_de_disable
 *
 * Description:
 *   禁用显示引擎
 *
 ****************************************************************************/

void d13x_de_disable(void)
{
  /* 禁用时序 */

  de_write(TIMING_CTRL, 0);

  /* 触发配置更新 */

  de_write(DE_CONFIG_UPDATE, DE_CONFIG_UPDATE_EN);

  iinfo("Display Engine disabled\n");
}

