input.content:
/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_panel.c
 *
 * D13x LCD 面板驱动 (4.3寸面板, 1024x600)
 * 参考: luban-lite panel_dsi_xm91080.c
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <debug.h>
#include "chip.h"
#include "artinchip_dsi.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* 面板时序参数 (4.3寸面板, 1024x600@60Hz) */

#define PANEL_H_ACTIVE          1024
#define PANEL_V_ACTIVE          600
#define PANEL_HFP               160
#define PANEL_HBP               160
#define PANEL_HSYNC             40
#define PANEL_VFP               10
#define PANEL_VBP               20
#define PANEL_VSYNC             8
#define PANEL_PIXEL_CLOCK       51200000  /* 51.2MHz */

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: panel_dsi_write_cmd
 *
 * Description:
 *   发送 DSI 命令
 *
 ****************************************************************************/

static int panel_dsi_write_cmd(uint8_t *cmd, uint32_t len)
{
  /* 简化: 直接写入 DSI 命令寄存器 */

  uint32_t timeout = 1000000;

  /* 等待命令 FIFO 空 */

  while (!(getreg32(D13X_MIPI_DSI_BASE + 0x58) & BIT(0)))
    {
      if (--timeout == 0)
        {
          return -ETIMEDOUT;
        }
      up_udelay(1);
    }

  /* 发送命令 */

  for (uint32_t i = 0; i < len; i++)
    {
      putreg32(cmd[i], D13X_MIPI_DSI_BASE + 0x20);
    }

  return OK;
}

/****************************************************************************
 * Name: panel_send_dcs_cmd
 *
 * Description:
 *   发送 DCS 命令
 *
 ****************************************************************************/

static int panel_send_dcs_cmd(uint8_t cmd, uint8_t *params, uint32_t len)
{
  uint8_t buf[16];

  buf[0] = 0x15;  /* DCS Short Write */
  buf[1] = cmd;

  for (uint32_t i = 0; i < len && i < 14; i++)
    {
      buf[2 + i] = params[i];
    }

  return panel_dsi_write_cmd(buf, 2 + len);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: d13x_panel_init
 *
 * Description:
 *   初始化 LCD 面板
 *
 ****************************************************************************/

int d13x_panel_init(void)
{
  uint8_t params[16];

  iinfo("Initializing 4.3\" LCD panel (1024x600)...\n");

  /* 等待面板稳定 */

  up_mdelay(100);

  /* 退出睡眠模式 */

  params[0] = 0x11;  /* Sleep Out */
  panel_send_dcs_cmd(0x11, NULL, 0);
  up_mdelay(120);

  /* 设置像素格式 */

  params[0] = 0x55;  /* RGB888 */
  panel_send_dcs_cmd(0x3A, params, 1);

  /* 设置显示方向 (可选) */

  params[0] = 0x00;  /* 正常方向 */
  panel_send_dcs_cmd(0x36, params, 1);

  /* 打开显示 */

  params[0] = 0x29;  /* Display ON */
  panel_send_dcs_cmd(0x29, NULL, 0);
  up_mdelay(50);

  iinfo("LCD panel initialized\n");
  return OK;
}

/****************************************************************************
 * Name: d13x_panel_enable
 *
 * Description:
 *   使能面板显示
 *
 ****************************************************************************/

void d13x_panel_enable(void)
{
  uint8_t params[1];

  /* 打开显示 */

  params[0] = 0x29;  /* Display ON */
  panel_send_dcs_cmd(0x29, NULL, 0);
  up_mdelay(20);

  iinfo("LCD panel enabled\n");
}

/****************************************************************************
 * Name: d13x_panel_disable
 *
 * Description:
 *   禁用面板显示
 *
 ****************************************************************************/

void d13x_panel_disable(void)
{
  uint8_t params[1];

  /* 关闭显示 */

  params[0] = 0x28;  /* Display OFF */
  panel_send_dcs_cmd(0x28, NULL, 0);
  up_mdelay(20);

  iinfo("LCD panel disabled\n");
}

/****************************************************************************
 * Name: d13x_panel_get_timing
 *
 * Description:
 *   获取面板时序参数
 *
 ****************************************************************************/

void d13x_panel_get_timing(uint32_t *hactive, uint32_t *vactive,
                           uint32_t *hfp, uint32_t *hbp, uint32_t *hsync,
                           uint32_t *vfp, uint32_t *vbp, uint32_t *vsync,
                           uint32_t *pixel_clock)
{
  if (hactive)
    {
      *hactive = PANEL_H_ACTIVE;
    }

  if (vactive)
    {
      *vactive = PANEL_V_ACTIVE;
    }

  if (hfp)
    {
      *hfp = PANEL_HFP;
    }

  if (hbp)
    {
      *hbp = PANEL_HBP;
    }

  if (hsync)
    {
      *hsync = PANEL_HSYNC;
    }

  if (vfp)
    {
      *vfp = PANEL_VFP;
    }

  if (vbp)
    {
      *vbp = PANEL_VBP;
    }

  if (vsync)
    {
      *vsync = PANEL_VSYNC;
    }

  if (pixel_clock)
    {
      *pixel_clock = PANEL_PIXEL_CLOCK;
    }
}

