static int d13x_fb_pandisplay(struct fb_vtable_s *vtable,
                              struct fb_planeinfo_s *pinfo)
{
  struct d13x_fb_info_s *fbi = &g_d13x_fb;
  void *fb_addr;

  if (!vtable || !pinfo || !fbi->initialized)
    {
      return -EINVAL;
    }

  /* 根据 yoffset 计算帧缓冲地址 */

  fb_addr = (void *)((uint32_t)fbi->fb_mem + pinfo->yoffset * fbi->fb_size / (D13X_FB_HEIGHT * D13X_FB_BUFFER_COUNT));

  iinfo("pandisplay: yoffset=%d, addr=0x%08x\n", pinfo->yoffset, (uint32_t)fb_addr);

#ifdef CONFIG_D13X_DISPLAY
  /* 更新显示引擎帧缓冲地址 */

  d13x_de_set_framebuffer((uint32_t)fb_addr);
#endif

  return OK;
}

